def main():
    base = PT.read_text(encoding="utf-8")
    for col, pasta in ((1, "en"), (2, "es")):
        html = base
        for linha in TRADUCOES:
            pt, alvo = linha[0], linha[col]
            if pt not in html:
                raise SystemExit(f"[{pasta}] trecho não encontrado: {pt[:70]}")
            html = html.replace(pt, alvo)
        destino = RAIZ / "src/static" / pasta / "index.html"
        destino.parent.mkdir(parents=True, exist_ok=True)
        destino.write_text(html, encoding="utf-8")
        print(f"gerado: src/static/{pasta}/index.html")


if __name__ == "__main__":
    main()
